import java.util.ArrayList;

public class GranjaRender {

    private ArrayList<Trabajo> trabajos;
    private ArrayList<Nodo> nodos;
    private ArrayList<Lote> lotes;

    public GranjaRender() {
        this.trabajos = new ArrayList<>();
        this.nodos = new ArrayList<>();
        this.lotes = new ArrayList<>();
    }

    // Obtiene el precio y el tiempo sin registrar ni cobrar el trabajo.
    public String cotizar(Trabajo trabajo) {
        // Comprueba que se haya proporcionado un trabajo.
        if (trabajo == null) {
            throw new IllegalArgumentException(
                "Debe proporcionar un trabajo."
            );
        }

        // Consulta los cálculos definidos por la categoría del trabajo.
        return String.format(
            "Costo: Q%.2f | Tiempo de entrega: %d horas",
            trabajo.calcularCosto(),
            trabajo.calcularTiempoEntrega()
        );
    }

    // Comprueba que un trabajo pueda incorporarse a la granja.
    private void validarTrabajoNuevo(Trabajo trabajo) {
        // Rechaza referencias inexistentes.
        if (trabajo == null) {
            throw new IllegalArgumentException(
                "Debe proporcionar un trabajo."
            );
        }

        // Solo admite trabajos nuevos que estén en cola.
        if (trabajo.getEstado() != Trabajo.EstadoTrabajo.EN_COLA
                || trabajo.getIntentos() != 0
                || trabajo.getIngresoRegistro() != 0
                || trabajo.getIngresoReintentos() != 0) {
            throw new IllegalArgumentException(
                "El trabajo debe ser nuevo, estar en cola y no tener ingresos."
            );
        }

        // Revisa todos los códigos registrados.
        for (Trabajo existente : trabajos) {
            // Rechaza un código que ya pertenece a otro trabajo.
            if (existente.getCodigo().equals(trabajo.getCodigo())) {
                throw new IllegalArgumentException(
                    "Ya existe un trabajo con ese código."
                );
            }
        }
    }

    // Registra un trabajo y cobra su costo completo.
    public void registrarTrabajo(Trabajo trabajo) {
        // Valida antes de modificar ingresos o listas.
        validarTrabajoNuevo(trabajo);

        // Registra el cobro dentro del trabajo.
        trabajo.cobrarRegistro();

        // Incorpora el trabajo a la granja.
        trabajos.add(trabajo);
    }

    // Incorpora los datos iniciales sin generar ingresos.
    public void agregarTrabajoInicial(Trabajo trabajo) {
        // Aplica las mismas validaciones de registro.
        validarTrabajoNuevo(trabajo);

        // Agrega el trabajo sin cobrarlo.
        trabajos.add(trabajo);
    }

    // Registra un nodo con código único.
    public void registrarNodo(Nodo nodo) {
        // Rechaza una referencia inexistente.
        if (nodo == null) {
            throw new IllegalArgumentException(
                "Debe proporcionar un nodo."
            );
        }

        // Comprueba que el nodo ingrese libre.
        if (nodo.isOcupado()) {
            throw new IllegalArgumentException(
                "El nodo debe estar libre al registrarse."
            );
        }

        // Recorre los nodos registrados.
        for (Nodo existente : nodos) {
            // Rechaza códigos duplicados.
            if (existente.getCodigo().equals(nodo.getCodigo())) {
                throw new IllegalArgumentException(
                    "Ya existe un nodo con ese código."
                );
            }
        }

        // Guarda el nodo validado.
        nodos.add(nodo);
    }

    // Busca un trabajo registrado mediante su código.
    public Trabajo buscarTrabajo(String codigo) {
        // Valida el código recibido.
        if (codigo == null || codigo.trim().isEmpty()) {
            throw new IllegalArgumentException(
                "El código del trabajo no puede estar vacío."
            );
        }

        // Recorre los trabajos buscando una coincidencia.
        for (Trabajo trabajo : trabajos) {
            // Devuelve el trabajo encontrado.
            if (trabajo.getCodigo().equals(codigo.trim())) {
                return trabajo;
            }
        }

        // Informa que no existe el código solicitado.
        throw new IllegalArgumentException(
            "No existe un trabajo con ese código."
        );
    }

    // Busca un nodo registrado mediante su código.
    public Nodo buscarNodo(String codigo) {
        // Valida el código recibido.
        if (codigo == null || codigo.trim().isEmpty()) {
            throw new IllegalArgumentException(
                "El código del nodo no puede estar vacío."
            );
        }

        // Recorre los nodos registrados.
        for (Nodo nodo : nodos) {
            // Devuelve el nodo encontrado.
            if (nodo.getCodigo().equals(codigo.trim())) {
                return nodo;
            }
        }

        // Informa que el nodo no existe.
        throw new IllegalArgumentException(
            "No existe un nodo con ese código."
        );
    }

    // Busca un lote mediante su código.
    public Lote buscarLote(String codigo) {
        // Valida el código recibido.
        if (codigo == null || codigo.trim().isEmpty()) {
            throw new IllegalArgumentException(
                "El código del lote no puede estar vacío."
            );
        }

        // Recorre los lotes creados.
        for (Lote lote : lotes) {
            // Devuelve el lote encontrado.
            if (lote.getCodigo().equals(codigo.trim())) {
                return lote;
            }
        }

        // Informa que el lote no existe.
        throw new IllegalArgumentException(
            "No existe un lote con ese código."
        );
    }

    // Crea un lote en el nodo indicado.
    public Lote crearLote(String codigoNodo) {
        Nodo nodo = buscarNodo(codigoNodo);

        // Genera códigos consecutivos: L1, L2, L3...
        // No se eliminan lotes, por lo que no se repiten.
        String codigoLote = "L" + (lotes.size() + 1);
        Lote lote = new Lote(codigoLote, nodo);

        // Guarda el lote después de que su constructor reserve el nodo.
        lotes.add(lote);

        // Devuelve el lote para poder mostrar su código.
        return lote;
    }

    // Busca los objetos y solicita al lote que asigne el trabajo.
    public void asignarTrabajo(String codigoLote, String codigoTrabajo) {
        Lote lote = buscarLote(codigoLote);
        Trabajo trabajo = buscarTrabajo(codigoTrabajo);

        // El lote valida la capacidad, compatibilidad y estado.
        lote.asignarTrabajo(trabajo);
    }

    // Solicita retirar un trabajo del lote indicado.
    public void retirarTrabajo(String codigoLote, String codigoTrabajo) {
        Lote lote = buscarLote(codigoLote);
        Trabajo trabajo = buscarTrabajo(codigoTrabajo);

        // El lote comprueba la pertenencia y devuelve el trabajo a la cola.
        lote.retirarTrabajo(trabajo);
    }

    // Inicia el lote identificado por su código.
    public void iniciarLote(String codigoLote) {
        Lote lote = buscarLote(codigoLote);

        // Delega las validaciones y el inicio en el lote.
        lote.iniciar();
    }

    // Registra el resultado de un trabajo en un lote.
    public void registrarResultado(String codigoLote,
                                   String codigoTrabajo,
                                   boolean completado) {
        Lote lote = buscarLote(codigoLote);
        Trabajo trabajo = buscarTrabajo(codigoTrabajo);

        // El lote controla duplicados, resultados pendientes y cierre.
        lote.registrarResultado(trabajo, completado);
    }

    // Obtiene las categorías presentes sin repetir sus nombres.
    private ArrayList<String> obtenerCategorias() {
        ArrayList<String> categorias = new ArrayList<>();

        // Consulta la categoría de cada trabajo mediante polimorfismo.
        for (Trabajo trabajo : trabajos) {
            String categoria = trabajo.getCategoria();

            // Agrega solamente las categorías que aún no están en la lista.
            if (!categorias.contains(categoria)) {
                categorias.add(categoria);
            }
        }

        // Devuelve las categorías encontradas.
        return categorias;
    }

    // Cuenta los trabajos de cada categoría en cada estado.
    public String contarPorCategoriaYEstado() {
        // Informa cuando no existen trabajos.
        if (trabajos.isEmpty()) {
            return "No hay trabajos registrados.";
        }

        String reporte = "";

        // Genera una sección por categoría.
        for (String categoria : obtenerCategorias()) {
            // Agrega el nombre de la categoría.
            reporte += categoria + ":\n";

            // Recorre todos los estados definidos en Trabajo.
            for (Trabajo.EstadoTrabajo estado
                    : Trabajo.EstadoTrabajo.values()) {
                int cantidad = 0;

                // Cuenta coincidencias de categoría y estado.
                for (Trabajo trabajo : trabajos) {
                    // Comprueba ambas condiciones.
                    if (trabajo.getCategoria().equals(categoria)
                            && trabajo.getEstado() == estado) {
                        // Incrementa el contador.
                        cantidad++;
                    }
                }

                // Incluye también estados con cero trabajos.
                reporte += "  " + estado + ": " + cantidad + "\n";
            }
        }

        // Devuelve el reporte completo.
        return reporte;
    }

    // Calcula ingresos totales, por registro, por reintentos y categoría.
    public String reporteIngresos() {
        double registro = 0.0;
        double reintentos = 0.0;

        // Calcula los totales a partir de los ingresos de cada trabajo.
        for (Trabajo trabajo : trabajos) {
            // Acumula los cobros de registro.
            registro += trabajo.getIngresoRegistro();

            // Acumula los cargos por reintentos.
            reintentos += trabajo.getIngresoReintentos();
        }

        String reporte = String.format(
            "Ingresos por registro: Q%.2f\n"
            + "Ingresos por reintentos: Q%.2f\n"
            + "Ingreso total: Q%.2f\n",
            registro, reintentos, registro + reintentos
        );

        // Calcula los ingresos de cada categoría presente.
        for (String categoria : obtenerCategorias()) {
            double totalCategoria = 0.0;

            // Revisa todos los trabajos.
            for (Trabajo trabajo : trabajos) {
                // Selecciona los trabajos de la categoría actual.
                if (trabajo.getCategoria().equals(categoria)) {
                    // Suma ambos tipos de ingreso.
                    totalCategoria += trabajo.getIngresoRegistro()
                            + trabajo.getIngresoReintentos();
                }
            }

            // Presenta los montos con dos decimales.
            reporte += String.format(
                "%s: Q%.2f\n", categoria, totalCategoria
            );
        }

        // Devuelve el reporte calculado.
        return reporte;
    }

    // Muestra los lotes que siguen en preparación o ejecución.
    public String reporteLotesAbiertos() {
        String reporte = "";

        // Recorre todos los lotes.
        for (Lote lote : lotes) {
            // Excluye los lotes cerrados.
            if (!lote.getEstado().equals("CERRADO")) {
                // Incluye nodo, horas asignadas y capacidad disponible.
                reporte += lote.toString() + "\n";
            }
        }

        // Informa si no encontró lotes abiertos.
        if (reporte.isEmpty()) {
            return "No hay lotes abiertos.";
        }

        // Devuelve el reporte.
        return reporte;
    }

    // Muestra la información de todos los trabajos registrados.
    public String listarTrabajos() {
        // Informa si la lista está vacía.
        if (trabajos.isEmpty()) {
            return "No hay trabajos registrados.";
        }

        String reporte = "";

        // Recorre los trabajos registrados.
        for (Trabajo trabajo : trabajos) {
            // Presenta su identificación, estado, intentos y horas.
            reporte += "Código: " + trabajo.getCodigo()
                    + " | Categoría: " + trabajo.getCategoria()
                    + " | Estado: " + trabajo.getEstado()
                    + " | Intentos: " + trabajo.getIntentos()
                    + " | Horas estimadas: " + trabajo.getHorasEstimadas()
                    + "\n";
        }

        // Devuelve el listado.
        return reporte;
    }

    // Muestra la información de todos los nodos registrados.
    public String listarNodos() {
        // Informa si la lista está vacía.
        if (nodos.isEmpty()) {
            return "No hay nodos registrados.";
        }

        String reporte = "";

        // Recorre los nodos.
        for (Nodo nodo : nodos) {
            // Utiliza la descripción definida en Nodo.
            reporte += nodo.toString() + "\n";
        }

        // Devuelve el listado.
        return reporte;
    }
}